<?php
namespace App\Http\Controllers\Admin;use App\Http\Controllers\Controller;use App\Models\Page;use Illuminate\Http\Request;use Illuminate\Support\Str;class PageController extends Controller{public function index(){return view('admin.pages.index',['items'=>Page::orderBy('section')->orderBy('sort')->paginate(30)]);}public function create(){return view('admin.pages.form',['item'=>new Page]);}public function store(Request $r){Page::create($this->data($r));return redirect()->route('admin.pages.index')->with('ok','Страница создана');}public function edit(Page $page){return view('admin.pages.form',['item'=>$page]);}public function update(Request $r,Page $page){$page->update($this->data($r));return redirect()->route('admin.pages.index')->with('ok','Страница обновлена');}public function destroy(Page $page){$page->delete();return back();}private function data(Request $r){$d=$r->validate(['title'=>'required|max:255','section'=>'nullable|max:100','excerpt'=>'nullable','content'=>'nullable','meta_title'=>'nullable|max:255','meta_description'=>'nullable|max:500','sort'=>'nullable|integer']);$d['slug']=Str::slug($r->input('slug')?:$d['title']);$d['is_published']=$r->boolean('is_published');return $d;}}